import{_ as e,o as a,c as s,a0 as d}from"./chunks/framework.Bmhw_dvp.js";const k=JSON.parse('{"title":"HTTPS 证书","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/https.md","filePath":"advanced/https.md","lastUpdated":1793354072000}'),i={name:"advanced/https.md"};function o(c,t,n,l,r,h){return a(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="https-证书" tabindex="-1">HTTPS 证书 <a class="header-anchor" href="#https-证书" aria-label="Permalink to &quot;HTTPS 证书&quot;">​</a></h1><p>HTTPS 由后端在同进程提供（<code>HTTPS=true</code>），证书由后端自带的签发子命令生成。</p><h2 id="签发方式选择" tabindex="-1">签发方式选择 <a class="header-anchor" href="#签发方式选择" aria-label="Permalink to &quot;签发方式选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>地址类型</th><th>证书</th><th>说明</th></tr></thead><tbody><tr><td><code>localhost</code></td><td>自签</td><td>SAN 含 <code>localhost</code>、<code>127.0.0.1</code>、<code>::1</code>，10 年有效</td></tr><tr><td>域名</td><td>Let&#39;s Encrypt</td><td>内置 ACME 客户端自动申请，浏览器无警告</td></tr><tr><td>公网 IP</td><td>Let&#39;s Encrypt</td><td>支持 IP 证书（含 IPv6）</td></tr><tr><td>内网 IP</td><td>自签</td><td>SAN 写入 IP 条目</td></tr></tbody></table><p>工具会自行判断域名 / IP（<code>identifierType</code> 的 <code>dns</code> 与 <code>ip</code>）再选签发方式；<code>--selfsigned</code> 可强制自签。</p><blockquote><p><strong>正式环境不建议用命令行自动签发正式证书</strong>：菜单里的 Let&#39;s Encrypt 签发适合测试，续期与验证失败排查都要自己盯。生产建议把域名交给 Cloudflare、阿里云 ESA、腾讯 EdgeOne 等支持自动签发的边缘服务，或用宝塔、1Panel 等面板统一申请续期，再反代到 3333 端口。</p></blockquote><h2 id="签发命令" tabindex="-1">签发命令 <a class="header-anchor" href="#签发命令" aria-label="Permalink to &quot;签发命令&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 域名 → Let&#39;s Encrypt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.2.3.4</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 公网 IP → Let&#39;s Encrypt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.1.1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 内网 IP → 自签</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 强制重新签发</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 签发证书 + HTTPS 启动</span></span></code></pre></div><p>Linux 下把 <code>start.bat</code> 换成 <code>./start.sh</code>。启动脚本实际调的是 <code>zviewer-backend --gen-cert &lt;host&gt;</code>。</p><h2 id="let-s-encrypt-前置条件" tabindex="-1">Let&#39;s Encrypt 前置条件 <a class="header-anchor" href="#let-s-encrypt-前置条件" aria-label="Permalink to &quot;Let&#39;s Encrypt 前置条件&quot;">​</a></h2><ol><li>域名解析到本机公网 IP，或公网 IP 直接指向本机。</li><li>本机 <strong>80 端口</strong>空闲且防火墙放行（HTTP-01 验证需要）。</li><li>正式环境每个域名每周限签 5 张；调试加 <code>--staging</code> 用测试环境。</li></ol><h2 id="证书文件" tabindex="-1">证书文件 <a class="header-anchor" href="#证书文件" aria-label="Permalink to &quot;证书文件&quot;">​</a></h2><p>输出在 <code>config/ssl/</code>：</p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th></tr></thead><tbody><tr><td><code>cert.pem</code></td><td>证书（CA 模式写入完整 fullchain）</td></tr><tr><td><code>key.pem</code></td><td>私钥</td></tr><tr><td><code>acme-account.key</code></td><td>ACME 账号密钥（自动生成并复用，避免每次重建账号）</td></tr></tbody></table><h2 id="实现" tabindex="-1">实现 <a class="header-anchor" href="#实现" aria-label="Permalink to &quot;实现&quot;">​</a></h2><p>签发是后端的一个子命令（<code>backend-go/internal/ssl</code>），自签与 ACME 都是纯 Go 实现，不依赖 <code>openssl</code> 或 Node 的证书包。</p><h3 id="自签流程" tabindex="-1">自签流程 <a class="header-anchor" href="#自签流程" aria-label="Permalink to &quot;自签流程&quot;">​</a></h3><p>现场生成密钥对与 X.509 证书，SAN 按地址类型填充（<code>localhost</code> 写入 <code>localhost</code> / <code>127.0.0.1</code> / <code>::1</code>，内网 IP 写入 IP 条目），有效期 10 年。</p><h3 id="acme-流程" tabindex="-1">ACME 流程 <a class="header-anchor" href="#acme-流程" aria-label="Permalink to &quot;ACME 流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>directory → newNonce → newAccount → newOrder</span></span>
<span class="line"><span>  → http-01 challenge（本地起 HTTP 服务器响应验证，默认 80 端口）</span></span>
<span class="line"><span>  → finalize(CSR) → 轮询订单 → 下载证书链（写入 cert.pem 为 fullchain）</span></span></code></pre></div><ul><li>目录端点：正式 <code>https://acme-v02.api.letsencrypt.org/directory</code>，<code>--staging</code> 切到 <code>acme-staging-v02</code>（无速率限制）。</li><li>请求超时 30s，订单轮询间隔 3s。</li><li>账号密钥持久化在 <code>acme-account.key</code>，后续复用同一账号。</li></ul><h3 id="命令行选项" tabindex="-1">命令行选项 <a class="header-anchor" href="#命令行选项" aria-label="Permalink to &quot;命令行选项&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>作用</th></tr></thead><tbody><tr><td><code>--force</code> / <code>-f</code></td><td>强制重新生成，不检查是否已存在</td></tr><tr><td><code>--selfsigned</code></td><td>强制自签（即使指定了域名或公网 IP）</td></tr><tr><td><code>--staging</code></td><td>使用 Let&#39;s Encrypt 测试环境</td></tr><tr><td><code>--email &lt;邮箱&gt;</code></td><td>ACME 账号邮箱（可选）</td></tr><tr><td><code>--directory &lt;url&gt;</code></td><td>自定义 ACME 目录 URL（高级）</td></tr></tbody></table><h3 id="后端启用" tabindex="-1">后端启用 <a class="header-anchor" href="#后端启用" aria-label="Permalink to &quot;后端启用&quot;">​</a></h3><p><code>HTTPS=true</code> 时后端以 TLS 监听 3333；证书缺失会自动签一张本机自签证书再启动，不会因为少了证书直接退出。证书路径可用 <code>SSL_CERT_PATH</code> / <code>SSL_KEY_PATH</code> 覆盖。HTTP 与 HTTPS 二选一，不存在双端口并存。</p><p>启用 HTTPS 后请求视为安全上下文，认证 cookie 会带 <code>secure</code> 属性并经 httpOnly cookie 下发，而不是 HTTP 下的 Bearer 回退，见<a href="/advanced/auth">鉴权与权限模型</a>。单文件版启动脚本的 <code>https</code> 子命令会自动带上该变量。</p><h2 id="https-模式与自签提示" tabindex="-1">HTTPS 模式与自签提示 <a class="header-anchor" href="#https-模式与自签提示" aria-label="Permalink to &quot;HTTPS 模式与自签提示&quot;">​</a></h2><p><code>start.bat https</code> 之后，页面与 API 统一在 <code>https://localhost:3333</code>，WebRTC（屏幕共享与语音）要求 HTTPS 环境。</p><p><code>localhost</code> 与内网 IP 的自签证书不被浏览器信任，会看到安全警告：把 <code>config/ssl/cert.pem</code> 导入客户端「受信任的根证书颁发机构」，或改用域名 / 公网 IP 走 Let&#39;s Encrypt。</p><p>Docker 部署不自动签发证书，HTTPS 宜前置 Nginx / Caddy 反代。IPv6 直连时证书 SAN 需包含该地址（Let&#39;s Encrypt 支持公网 IPv6）。</p>`,30)])])}const b=e(i,[["render",o]]);export{k as __pageData,b as default};
